  { match: /^(gpt|codex|o[134]|chatgpt|dall)/u, provider: "openai" },
  { match: /^claude/u, provider: "anthropic" },
  { match: /^(gemini|gemma|palm)/u, provider: "google" },
  { match: /^deepseek/u, provider: "deepseek" },
